static BOOL __stdcall GetSourceLineWithRetry(HANDLE hProcess, DWORD nAddress, void * pdwDisplacement, void * pLine) {
    if (!pSymGetLineFromAddr) {
      return 0;
    }

    int nSearchOffset = 0;
    BOOL bLineFound = (*pSymGetLineFromAddr)(hProcess, nAddress, pdwDisplacement, pLine);
    if (bLineFound) {
      return 1;
    }

    do {
      nSearchOffset++;
      if (nSearchOffset == 100) {
        return 0;
      }

      bLineFound = (*pSymGetLineFromAddr)(hProcess, nAddress - nSearchOffset, pdwDisplacement, pLine);
    } while (!bLineFound);

    if (!nSearchOffset) {
      return 1;
    }

    *(int*)pdwDisplacement = nSearchOffset;
    return 1;
}

